# -*- coding: utf-8 -*-
"""2026-11-01 daily: Meta ad accounts (Saudi Arabia, France, Switzerland), Instagram disabled (France, Germany),
Facebook disabled (Qatar), Snapchat locked (France, USA). Modeled on the converting country pages."""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'dd29'))
from fams import *
from lib import PAGES
IGAPP = A('/guides/instagram-account-suspended-appeal/', 'how to appeal an Instagram suspension')
ACE = A('/appeals-centre-europe-instagram-facebook-suspension/', 'Appeals Centre Europe')
ADHUB = A('/ad-account-recovery/', 'Meta ad account recovery')
NOPASS_AD = ('Can an agency get my ad account back faster?', 'No one can speed up Meta. A clear, accurate appeal with documents that match is what helps. Meta makes the final decision.')
ADSTEPS = ol(['Open Account Quality in Meta Business Suite and screenshot the notice before changing anything.',
              'Work out which asset is limited: the ad account, the business portfolio, a Page or an admin profile.',
              'Clear any unpaid balance and remove payment methods that are not in the business name.',
              'Make the business name and address match across the portfolio, the ad account, the website and your documents.',
              'Request one review, with a short note that explains what the business does.'])
IGSTEPS = ol(['Screenshot the notice, with the date and any deadline shown.',
              'Appeal from the notice in the app, once, with accurate details.',
              'Do the video selfie or ID check if Instagram asks for it.',
              'Keep the final decision message. You need it for the next step.'])
SNSTEPS = ol(['Log in at accounts.snapchat.com from a browser and read what it says about the lock.',
              'If there is an Unlock option, the lock is temporary. Use it once it becomes available.',
              'Delete any unofficial Snapchat app, tweak or third-party add-on before you unlock.',
              'If the account is permanently locked, contact Snapchat Support through help.snapchat.com.',
              'Once you are back in, turn on two-factor authentication and check the email and number on the account.'])

page('meta-ad-account-disabled-saudi-arabia', 'ad', 'Meta Ad Account Disabled in Saudi Arabia: Help',
 'Saudi business with a disabled or restricted Meta ad account? CR, VAT and billing checks, Arabic documents and how to request a review.',
 'Meta ad account disabled and your business is in Saudi Arabia?', 'Meta ad account, Saudi Arabia',
 'From Riyadh, Jeddah or Dammam, the review in Account Quality is the route. Matching business details make the biggest difference.',
 'If Meta disabled the ad account of a Saudi business, open Account Quality, read the notice and request one review. Before you do, make sure the business name matches your Commercial Registration, the VAT details are correct in billing and the website shows a real address. Meta can ask for documents. Meta makes the final decision.',
 [('Match the CR', 'Same business name as the Commercial Registration.'), ('Check billing', 'Card and VAT details in the business name.'), ('Appeal once', 'One clear review request.')],
 [S('Steps', ADSTEPS),
  S('Checks specific to Saudi Arabia', ul(['Use the business name exactly as it appears on the Commercial Registration, in English if the portfolio is in English.',
     'Add your VAT number in billing if the business is registered with ZATCA.', 'Show the national address and a working contact page on the website the ads point to.',
     'If an admin profile is a personal account with an Arabic name, make sure the same person can pass an ID check.'])),
  S('Arabic documents', 'Meta may accept Arabic documents, but a short English summary of what each one shows makes the review easier to follow. Use the same document each time you are asked. Related: %s, %s and %s.' % (ADHUB, A('/meta-ad-account-disabled-uae/', 'Meta ad account disabled in the UAE'), A('/facebook-account-disabled-saudi-arabia-what-to-do/', 'Facebook profile disabled in Saudi Arabia'))),
 ],
 [('Can I appeal in Arabic?', 'Yes. Keep it short and factual. Meta may reply in English.'), NOPASS_AD,
  ('Should I open a new ad account?', 'Not while the review is open. New accounts linked to the same people or cards can be restricted as well.')],
 ['Saudi businesses that advertise on Facebook and Instagram.', 'Agencies running ads for Saudi clients.', 'E-commerce stores selling across the Gulf.'], area='SA')

page('meta-ad-account-disabled-france', 'ad', 'Meta Ad Account Disabled in France: Appeal Help',
 'French business with a disabled or restricted Meta ad account? Kbis, SIRET, VAT and legal notice checks, the DSA, and how to request a review.',
 'Meta ad account disabled and your business is in France?', 'Meta ad account, France',
 'Meta checks whether a real business stands behind the ads. In France, your Kbis and the legal notice on your site do much of that work.',
 'If Meta disabled the ad account of a French business, open Account Quality, read the notice and request one review. Before you do, check that the name matches your Kbis or SIRET record, the VAT number is in billing and the site shows complete mentions legales. Meta makes the final decision.',
 [('Match the Kbis', 'Same name as the Kbis or SIRET record.'), ('Legal notice', 'Mentions legales complete on the site.'), ('Appeal once', 'One clear review request.')],
 [S('Steps', ADSTEPS),
  S('Checks specific to France', ul(['Use the company name from the Kbis extract, or the SIRET record for an auto-entrepreneur.',
     'Add your intra-EU VAT number in billing if you are registered.', 'Make sure the mentions legales page shows the company name, address, SIREN and a contact.',
     'Alcohol advertising in France sits under the Loi Evin. If you sell wine or spirits, check the ads against it before you appeal.'])),
  S('Your rights in the EU', 'Under the Digital Services Act, Meta has to explain restrictions on business accounts too. Keep the statement of reasons. Arcom is the French coordinator for the DSA. Related: %s, %s and %s.' % (ADHUB, A('/meta-ad-account-disabled-germany/', 'Meta ad account disabled in Germany'), A('/fr/', 'Unbanz en francais'))),
 ],
 [('Can I appeal in French?', 'Yes. Write in French or English. Clear facts matter more than the language.'), NOPASS_AD,
  ('Is there information in French?', 'Yes. Our French pages are at unbanz.com/fr/.')],
 ['French companies and auto-entrepreneurs.', 'E-commerce stores selling in France and Belgium.', 'Agencies running ads for French clients.'], area='FR')

page('meta-ad-account-disabled-switzerland', 'ad', 'Meta Ad Account Disabled in Switzerland: Help',
 'Swiss business with a disabled or restricted Meta ad account? UID, commercial register, VAT and Impressum checks, and how to request a review.',
 'Meta ad account disabled and your business is in Switzerland?', 'Meta ad account, Switzerland',
 'Zurich, Geneva, Basel or Lugano: the review in Account Quality is the route, and Swiss records make your business easy to verify.',
 'If Meta disabled the ad account of a Swiss business, open Account Quality, read the notice and request one review. Before you do, check that the name matches the commercial register and UID, the VAT number is in billing and the site has a clear Impressum. Meta makes the final decision on every review.',
 [('Match the register', 'Same name as the commercial register and UID.'), ('Impressum', 'Clear company details on the site.'), ('Appeal once', 'One clear review request.')],
 [S('Steps', ADSTEPS),
  S('Checks specific to Switzerland', ul(['Use the company name and UID (CHE number) exactly as they appear in the commercial register.',
     'Add your VAT number in billing if you are registered.', 'Swiss law expects online shops to show who they are. Put the company name, address and contact in the Impressum.',
     'If the ad account bills in euro but the business is Swiss, say why in the review note.'])),
  S('Switzerland is not in the EU', 'The EU Digital Services Act routes do not apply to Swiss businesses in the same way. The Swiss data protection act still lets you ask Meta for the personal data it holds. Related: %s, %s and %s.' % (ADHUB, A('/meta-ad-account-disabled-germany/', 'Meta ad account disabled in Germany'), A('/facebook-account-recovery-switzerland/', 'Facebook account recovery in Switzerland'))),
 ],
 [('Can I appeal in German, French or Italian?', 'Yes. Write in the language you are most comfortable with. Meta may reply in English.'), NOPASS_AD,
  ('Do I need a Swiss card on the ad account?', 'Not always, but the payment method should belong to the business or its owner.')],
 ['Swiss companies and sole proprietors.', 'Online shops selling in the DACH region.', 'Agencies running ads for Swiss clients.'], area=['CH'])

page('instagram-disabled-france-what-to-do', 'igsusp', 'Instagram Disabled in France: Your Options',
 'Your Instagram account was disabled and you live in France. The appeal, Appeals Centre Europe, your GDPR rights, 17Cyber for hacks and what to avoid.',
 'Instagram disabled your account and you live in France?', 'Instagram disabled, France',
 'In France you have the in-app appeal and, after that, the EU dispute route. Here is the order to use them in.',
 'If Instagram disabled your account and you live in France, appeal in the app first and keep the final decision. Under the Digital Services Act you can then take it to a certified dispute body such as Appeals Centre Europe, which works in French. If the account was hacked first, report it through 17Cyber or to the police.',
 [('Appeal in the app', 'Step one, from the notice.'), ('Dispute body', 'Appeals Centre Europe, in French.'), ('Hacked', '17Cyber or the police.')],
 [S('Steps', IGSTEPS),
  S('Routes in France', ul(['After a rejected appeal, file with %s using the reference from the decision.' % ACE,
     'The CNIL takes complaints if a GDPR data request is ignored.', 'Arcom is the French coordinator for the Digital Services Act.',
     'For a hack or a scam, 17Cyber on cybermalveillance.gouv.fr helps you report it. Keep the reference number.'])),
  S('Related', 'See %s, %s and %s.' % (IGAPP, A('/instagram-disabled-eu-what-to-do/', 'Instagram disabled in the EU'), A('/instagram-account-recovery-france/', 'Instagram account recovery in France'))),
 ],
 [('Can I write the appeal in French?', 'Yes. Instagram and Appeals Centre Europe both accept French.'),
  ('Can Arcom or the CNIL restore my account?', 'No. They supervise the rules. They do not switch accounts back on.'),
  ('Should I open a new account?', 'Not while the appeal is open. Meta says accounts made to get around a ban can be disabled too.')],
 ['Instagram users in France after a ban.', 'French creators and small businesses.', 'People whose appeal was rejected.'], area='FR')

page('instagram-disabled-germany-what-to-do', 'igsusp', 'Instagram Disabled in Germany: Your Options',
 'Your Instagram account was disabled and you live in Germany. The appeal, certified dispute bodies, your GDPR rights and reporting a hack to the police.',
 'Instagram disabled your account and you live in Germany?', 'Instagram disabled, Germany',
 'In Germany you have the in-app appeal and, after that, the EU dispute route. Here is the order to use them in.',
 'If Instagram disabled your account and you live in Germany, appeal in the app first and keep the final decision. Under the Digital Services Act you can then take it to a certified dispute body such as Appeals Centre Europe or User Rights. If the account was hacked first, report it to the police online.',
 [('Appeal in the app', 'Step one, from the notice.'), ('Dispute body', 'Appeals Centre Europe or User Rights.'), ('Hacked', 'Report it to the police.')],
 [S('Steps', IGSTEPS),
  S('Routes in Germany', ul(['After a rejected appeal, file with a certified dispute body such as %s or User Rights, using the reference from the decision.' % ACE,
     'Under Article 15 GDPR you can ask Meta for a copy of your personal data.', 'The Bundesnetzagentur is the German coordinator for the Digital Services Act.',
     'Most federal states run an online police station where you can report a hack or a scam.'])),
  S('Related', 'See %s, %s and %s.' % (IGAPP, A('/instagram-disabled-eu-what-to-do/', 'Instagram disabled in the EU'), A('/instagram-account-recovery-germany/', 'Instagram account recovery in Germany'))),
 ],
 [('Can I write the appeal in German?', 'Yes. Instagram and the dispute bodies accept German.'),
  ('Can the Bundesnetzagentur restore my account?', 'No. It supervises the rules. It does not switch accounts back on.'),
  ('Do I need a lawyer?', 'No. The dispute body route is built for individuals.')],
 ['Instagram users in Germany after a ban.', 'German creators and small businesses.', 'People whose appeal was rejected.'], area='DE')

page('facebook-account-disabled-qatar-what-to-do', 'fbdis', 'Facebook Disabled in Qatar: Your Options',
 'Your Facebook account was disabled and you are in Qatar. How to appeal, which ID to upload, reporting a hack and avoiding recovery scams.',
 'Facebook disabled your account and you are in Qatar?', 'Facebook disabled, Qatar',
 'From Doha or anywhere in Qatar, the appeal in the notice is the route. Here is how to give it the best chance.',
 'If Facebook disabled your account in Qatar, appeal once from the notice and upload ID if asked. A passport or Qatar ID works best when the name matches the profile. If the account was hacked or used to scam people, report it to the Ministry of Interior cybercrime unit and keep the reference number.',
 [('Appeal once', 'From the notice, with accurate details.'), ('Matching ID', 'Passport or QID, same name.'), ('Hacked', 'Report it and keep the reference.')],
 [S('Steps', ol(['Screenshot the notice with the date and any appeal deadline shown.',
                 'Appeal from the notice, logged in on the device you normally use.',
                 'If asked for ID, upload a clear photo of a passport or QID where the name matches the profile.',
                 'If you manage Pages or ad accounts, ask another admin to check them in Meta Business Suite.',
                 'Once you are back in, turn on two-factor authentication and remove devices you do not recognise.'])),
  S('ID checks from Qatar', 'If the profile name is in Arabic and your passport uses Latin letters, say so in the appeal and give both spellings. Use one document and the same one each time you are asked. Many residents in Qatar are expats, so mention a recent move if the profile shows logins from another country.'),
  S('Related', 'See %s, %s and %s.' % (A('/guides/facebook-account-disabled-appeal/', 'Facebook disabled: how to appeal'), A('/facebook-account-recovery-qatar/', 'Facebook account recovery in Qatar'), A('/instagram-disabled-qatar-what-to-do/', 'Instagram disabled in Qatar'))),
 ],
 [('Can I call Facebook?', 'Facebook does not offer phone support for disabled accounts. Numbers online that claim to be Facebook support are often scams.'),
  ('Can I write the appeal in Arabic?', 'Yes. Write in Arabic or English, whichever you are more comfortable with. Keep it short and factual.'),
  ('Will a new profile help?', 'Facebook allows one personal profile per person. A new one can be removed and can count against the appeal.')],
 ['Facebook users in Qatar after a ban.', 'Qatari businesses that run Pages and ads.', 'Residents and expats in Qatar.'], area='QA')

page('snapchat-account-locked-france', 'snap', 'Snapchat Account Locked in France: What to Do',
 'Snapchat locked your account and you live in France. Temporary or permanent, the unlock steps, Snapchat Support in French, and where to report a hack.',
 'Snapchat account locked in France?', 'Snapchat locked, France',
 'Snapchat is part of daily life for many people in France. Here is how to tell which lock you have and what to do next.',
 'If Snapchat locked your account in France, log in at accounts.snapchat.com to see whether the lock is temporary or permanent. A temporary lock shows an Unlock option once it is available. A permanent lock needs a request to Snapchat Support, which you can write in French. Remove unofficial apps first.',
 [('Check the lock', 'At accounts.snapchat.com.'), ('Remove add-ons', 'Unofficial apps and tweaks cause locks.'), ('Support in French', 'Through help.snapchat.com.')],
 [S('Steps', SNSTEPS),
  S('If someone else got in', 'If your email or number was changed by someone else, use the hacked-account steps rather than the unlock flow. See %s. You can report a hack or a scam through 17Cyber on cybermalveillance.gouv.fr. For cyberharassment, the 3018 line helps young people and their parents.' % A('/snapchat-hacked-no-access-to-email-or-phone/', 'Snapchat hacked with no access to email or phone')),
  S('Related', 'See %s and %s.' % (A('/snapchat-account-locked-temporary-or-permanent/', 'temporary or permanent lock'), A('/snapchat-permanently-banned-appeal/', 'Snapchat permanent ban appeal'))),
 ],
 [('Will deleting the app unlock it?', 'No. Reinstalling does not change the lock on the account.'),
  ('Can I write to Snapchat Support in French?', 'Yes. Write in French or English. Keep it short and factual.'),
  ('What happens to my memories?', 'Memories are tied to the account. If it comes back, they usually come back with it.')],
 ['Snapchat users in France with a locked account.', 'Parents helping a teenager who lost access.', 'Creators and businesses with a public profile.'], area='FR')

page('snapchat-account-locked-usa', 'snap', 'Snapchat Account Locked in the US: What to Do',
 'Snapchat locked your account and you are in the US. Temporary or permanent, the unlock steps, Snapchat Support, and where to report hacks or extortion.',
 'Snapchat account locked in the US?', 'Snapchat locked, US',
 'From a temporary lock after a new phone to a permanent ban, here is how to tell which one you have and what to do.',
 'If Snapchat locked your account in the US, log in at accounts.snapchat.com to see whether the lock is temporary or permanent. A temporary lock shows an Unlock option once it is available. A permanent lock needs a request to Snapchat Support at help.snapchat.com. Remove unofficial apps and tweaks before you try.',
 [('Check the lock', 'At accounts.snapchat.com.'), ('Remove add-ons', 'Unofficial apps and tweaks cause locks.'), ('Permanent ban', 'Contact Snapchat Support.')],
 [S('Steps', SNSTEPS),
  S('Common causes', ul(['Unofficial Snapchat versions, or apps that save snaps or add features.', 'Adding many people in a short time.',
     'Logging in from a new phone, a VPN or a new state.', 'Reports from other users.'])),
  S('Hacks, scams and extortion', 'If someone changed your email or number, use the hacked-account steps rather than the unlock flow. See %s. Report online scams and extortion to the FBI at ic3.gov. If anyone threatens to share private images, do not pay, keep the messages and report it.' % A('/snapchat-hacked-no-access-to-email-or-phone/', 'Snapchat hacked with no access to email or phone')),
 ],
 [('Will deleting the app unlock it?', 'No. Reinstalling does not change the lock on the account.'),
  ('Is there a Snapchat phone number?', 'No. Snapchat Support works through help.snapchat.com. Numbers online that claim to be Snapchat support are often scams.'),
  ('What happens to my memories?', 'Memories are tied to the account. If it comes back, they usually come back with it.')],
 ['Snapchat users in the US with a locked account.', 'Parents helping a teenager who lost access.', 'Creators and businesses with a public profile.'], area='US')
